// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DE DELIVERY (IFOOD, RAPPI, ANOTA AI, AIQFOME)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

let deliveryPlat = 'iFood';
if (body.orderId && body.code) deliveryPlat = 'iFood';
else if (body.rappi_order_id || body.store_id) deliveryPlat = 'Rappi';
else if (body.anota_id || body.customer_phone) deliveryPlat = 'Anota AI';
else deliveryPlat = 'Delivery App';

const customer = body.customer || {};
let rawPhone = (customer.phone?.number || customer.phone || body.customer_phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (customer.name || body.customer_name || 'Cliente Delivery').trim();
const orderId = (body.orderId || body.id || body.displayId || Date.now()).toString();
const numeroPedido = parseInt(orderId.replace(/\D/g, '').slice(-8) || Date.now().toString().slice(-8), 10);
const valorTotal = parseFloat(body.total?.orderAmount || body.order_total || body.total || 0);
const status = (body.code || body.status || 'PLACED').toUpperCase();

let statusOperacional = 'Pendente';
if (['CONFIRMED', 'PLACED', 'PREPARING', 'READY_TO_PICKUP'].includes(status)) {
  statusOperacional = 'Pago';
} else if (['DISPATCHED'].includes(status)) {
  statusOperacional = 'Enviado';
} else if (['CANCELLED'].includes(status)) {
  statusOperacional = 'Cancelado';
}

const items = (body.items || []).map(i => ({
  produto_nome: i.name || 'Item Delivery',
  quantidade: parseInt(i.quantity || 1, 10),
  preco_unitario: parseFloat(i.unitPrice || i.price || 0),
  observacao: i.observations || ''
}));

const dedupHash = crypto.createHash('sha256').update(`${deliveryPlat}_${orderId}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    delivery_plataforma: deliveryPlat,
    order_id: orderId,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_whatsapp: rawPhone,
    valor_total: valorTotal,
    status_operacional: statusOperacional,
    items: items
  }
}];
